import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"橫渠易說 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"橫渠易說 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/hengqu/059.md","filePath":"classics/hengqu/059.md"}'),l={name:"classics/hengqu/059.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><h3 id="彖曰-重巽以申命-剛巽乎中正而志行-柔皆順乎剛-是以小亨-利有攸往-利見大人。" tabindex="-1">彖曰：重巽以申命，剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。 <a class="header-anchor" href="#彖曰-重巽以申命-剛巽乎中正而志行-柔皆順乎剛-是以小亨-利有攸往-利見大人。" aria-label="Permalink to “彖曰：重巽以申命，剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。”">​</a></h3><h3 id="象曰-隨風巽-君子以申命行事。" tabindex="-1">象曰：隨風巽，君子以申命行事。 <a class="header-anchor" href="#象曰-隨風巽-君子以申命行事。" aria-label="Permalink to “象曰：隨風巽，君子以申命行事。”">​</a></h3><h3 id="初六-進退利武人之貞。-象曰-進退-志疑也-利武人之貞-志治也。" tabindex="-1">初六，進退利武人之貞。 象曰：“進退”，志疑也；“利武人之貞”，志治也。 <a class="header-anchor" href="#初六-進退利武人之貞。-象曰-進退-志疑也-利武人之貞-志治也。" aria-label="Permalink to “初六，進退利武人之貞。 象曰：“進退”，志疑也；“利武人之貞”，志治也。”">​</a></h3><p>體柔居下，在巽之始，謙抑過中，故施於武人之貞則適得其宜。進退者，柔不自決之象也。</p><h3 id="九二-巽在床下-用史巫紛若-吉無咎。-象曰-紛若之吉-得中也。" tabindex="-1">九二，巽在床下，用史巫紛若，吉無咎。 象曰：紛若之吉，得中也。 <a class="header-anchor" href="#九二-巽在床下-用史巫紛若-吉無咎。-象曰-紛若之吉-得中也。" aria-label="Permalink to “九二，巽在床下，用史巫紛若，吉無咎。 象曰：紛若之吉，得中也。”">​</a></h3><p>以陽居陰，其志下比，無應於上，故曰“巽在床下”。然不失中道，下為之用，故史巫紛若樂為之使，吉而無咎，非如上九喪其資斧。史巫，喻虛華過實者，言不失中道，則樂盡其誠者眾矣。</p><h3 id="九三-頻巽-吝。-象曰-頻巽之吝-志窮也。" tabindex="-1">九三，頻巽，吝。 象曰：頻巽之吝，志窮也。 <a class="header-anchor" href="#九三-頻巽-吝。-象曰-頻巽之吝-志窮也。" aria-label="Permalink to “九三，頻巽，吝。 象曰：頻巽之吝，志窮也。”">​</a></h3><p>三處陽剛，失巽之道，乘剛而動，頻吝所宜，志在比物，故吝，如復之六三志窮也。</p><h3 id="六四-悔亡-田獲三品。-象曰-田獲三品-有功也。" tabindex="-1">六四，悔亡，田獲三品。 象曰：“田獲三品”，有功也。 <a class="header-anchor" href="#六四-悔亡-田獲三品。-象曰-田獲三品-有功也。" aria-label="Permalink to “六四，悔亡，田獲三品。 象曰：“田獲三品”，有功也。”">​</a></h3><p>柔順之德，以陰居位，雖或乘剛，悔終可亡。近比於五，不為諂妄，而又二三併為所獲，不私其累而樂為己用，田獲之類也。使三陽見獲，四之功也。</p><h3 id="九五-貞吉悔亡-無不利-無初有終。先庚三日-後庚三日-吉。-象曰-九五之吉-位正中也。" tabindex="-1">九五，貞吉悔亡，無不利，無初有終。先庚三日，後庚三日，吉。 象曰：九五之吉，位正中也。 <a class="header-anchor" href="#九五-貞吉悔亡-無不利-無初有終。先庚三日-後庚三日-吉。-象曰-九五之吉-位正中也。" aria-label="Permalink to “九五，貞吉悔亡，無不利，無初有終。先庚三日，後庚三日，吉。 象曰：九五之吉，位正中也。”">​</a></h3><p>解見蠱卦。志不以正，則將有悔。“先庚三日”，讓始也；“後庚三日”，存終也；雖體陽居尊，無應於下，故不可為事之唱乃吉。不著於繇辭者，巽非憂患之時故也。</p><h3 id="上九-巽在床下-喪其資斧-貞兇。-象曰-巽在床下-上窮也-喪其資斧-正乎兇也。" tabindex="-1">上九，巽在床下，喪其資斧，貞兇。 象曰：“巽在床下”，上窮也；“喪其資斧”，正乎兇也。 <a class="header-anchor" href="#上九-巽在床下-喪其資斧-貞兇。-象曰-巽在床下-上窮也-喪其資斧-正乎兇也。" aria-label="Permalink to “上九，巽在床下，喪其資斧，貞兇。 象曰：“巽在床下”，上窮也；“喪其資斧”，正乎兇也。”">​</a></h3><p>柔巽過極，難為之下，物不為用，故曰“喪其資斧兇”。資斧尚喪，餘用殫矣。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
